class Solution {
  private static final long MOD = 1_000_000_007L;

  private static long pow(long b, long e) {
    long r = 1;
    for (b %= MOD; e > 0; e >>= 1) {
      if ((e & 1) == 1) r = r * b % MOD;
      b = b * b % MOD;
    }
    return r;
  }

  public int countVisiblePeople(int n, int pos, int k) {
    if (k > n - 1) return 0;
    long num = 1, den = 1;
    for (int i = 1; i <= k; i++) {
      num = num * (n - 1 - k + i) % MOD;
      den = den * i % MOD;
    }
    return (int) (2 * num % MOD * pow(den, MOD - 2) % MOD);
  }
}
